/**
 * Known domain mapping for tech stack and skills to fetch official favicons through Google.
 */
export const SKILL_DOMAIN_MAP: Record<string, string> = {
  "Next.js": "nextjs.org",
  "React": "react.dev",
  "Vue.js": "vuejs.org",
  "Vue": "vuejs.org",
  "TypeScript": "typescriptlang.org",
  "JavaScript": "js.org",
  "Tailwind CSS": "tailwindcss.com",
  "Bootstrap": "getbootstrap.com",
  "Flutter": "flutter.dev",
  "Node.js": "nodejs.org",
  "Express.js": "expressjs.com",
  "Python": "python.org",
  "Django": "djangoproject.com",
  "Java": "java.com",
  "C++": "isocpp.org",
  "Cpp": "isocpp.org",
  "PHP": "php.net",
  "Laravel": "laravel.com",
  "MySQL": "mysql.com",
  "PostgreSQL": "postgresql.org",
  "NeonDB": "neon.tech",
  "Neondb": "neon.tech",
  "Neon": "neon.tech",
  "Supabase": "supabase.com",
  "Git": "git-scm.com",
  "GitHub": "github.com",
  "VS Code": "code.visualstudio.com",
  "XAMPP": "apachefriends.org",
  "Xampp": "apachefriends.org",
  "Vercel": "vercel.com",
  "Prisma ORM": "prisma.io",
  "Prisma": "prisma.io",
  "Leaflet.js": "leafletjs.com",
  "Leaflet": "leafletjs.com",
  "Cloudinary": "cloudinary.com",
  "JSON Web Tokens (JWT)": "jwt.io",
  "JWT": "jwt.io",
};

/**
 * Generate Google Favicon API URL
 * @param domain Target website domain
 * @param size Requested pixel size (typically 64 or 128 for high-DPI displays)
 */
export function getGoogleFaviconUrl(domain: string, size: number = 64): string {
  return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=${size}`;
}

export interface GoogleSkillIconProps {
  name: string;
  domain?: string;
  className?: string;
  size?: number;
}

/**
 * GoogleSkillIcon renders verified technology brand icons.
 * Uses official vector SVGs with zero network latency and no external service dependencies.
 * Falls back safely to Google Favicon / Code2 icon if an unknown skill is requested.
 */
export function GoogleSkillIcon({
  name,
  domain,
  className = "w-4 h-4",
  size = 64,
}: GoogleSkillIconProps) {
  const [hasError, setHasError] = useState(false);

  const cleanName = name?.trim() || "";
  const key = cleanName.toLowerCase();

  // Match native SVGs
  if (key === "next.js" || key === "nextjs" || key === "next") {
    return <NextjsIcon className={className} />;
  }
  if (key === "react" || key === "react.js" || key === "reactjs") {
    return <ReactIcon className={className} />;
  }
  if (key === "typescript" || key === "ts") {
    return <TypeScriptIcon className={className} />;
  }
  if (key === "javascript" || key === "js") {
    return <JavaScriptIcon className={className} />;
  }
  if (key === "tailwind css" || key === "tailwindcss" || key === "tailwind") {
    return <TailwindIcon className={className} />;
  }
  if (key === "node.js" || key === "nodejs" || key === "node") {
    return <NodejsIcon className={className} />;
  }
  if (key === "postgresql" || key === "postgres") {
    return <PostgresIcon className={className} />;
  }
  if (key === "neondb" || key === "neon") {
    return <NeonIcon className={className} />;
  }
  if (key === "supabase") {
    return <SupabaseIcon className={className} />;
  }
  if (key === "prisma orm" || key === "prisma") {
    return <PrismaIcon className={className} />;
  }
  if (key === "cloudinary") {
    return <CloudinaryIcon className={className} />;
  }
  if (key === "vue.js" || key === "vuejs" || key === "vue") {
    return <VueIcon className={className} />;
  }
  if (key === "flutter") {
    return <FlutterIcon className={className} />;
  }
  if (key === "html" || key === "html5") {
    return <Html5Icon className={className} />;
  }
  if (key === "css" || key === "css3") {
    return <Css3Icon className={className} />;
  }
  if (key === "bootstrap") {
    return <BootstrapIcon className={className} />;
  }
  if (key === "express.js" || key === "expressjs" || key === "express") {
    return <ExpressIcon className={className} />;
  }
  if (key === "python") {
    return <PythonIcon className={className} />;
  }
  if (key === "django") {
    return <DjangoIcon className={className} />;
  }
  if (key === "java") {
    return <JavaIcon className={className} />;
  }
  if (key === "c++" || key === "cpp") {
    return <CppIcon className={className} />;
  }
  if (key === "laravel") {
    return <LaravelIcon className={className} />;
  }
  if (key === "php") {
    return <PhpIcon className={className} />;
  }
  if (key === "mysql") {
    return <MysqlIcon className={className} />;
  }
  if (key === "git") {
    return <GitIcon className={className} />;
  }
  if (key === "github") {
    return <GithubIcon className={className} />;
  }
  if (key === "vs code" || key === "vscode" || key === "visual studio code") {
    return <VsCodeIcon className={className} />;
  }
  if (key === "vercel") {
    return <VercelIcon className={className} />;
  }
  if (key === "xampp") {
    return <XamppIcon className={className} />;
  }
  if (key === "leaflet.js" || key === "leaflet" || key === "leafletjs") {
    return <LeafletIcon className={className} />;
  }
  if (key === "json web tokens (jwt)" || key === "jwt" || key === "json web tokens") {
    return <JwtIcon className={className} />;
  }
  if (key === "inquiry integration" || key === "inquiry") {
    return <InquiryIcon className={className} />;
  }

  // Graceful fallback for any future unmapped technology
  const resolvedDomain = domain || SKILL_DOMAIN_MAP[cleanName];
  if (!resolvedDomain || hasError) {
    return <Code2 className={`${className} text-cyan-400`} aria-hidden="true" />;
  }

  const iconUrl = getGoogleFaviconUrl(resolvedDomain, size);

  return (
    <Image
      src={iconUrl}
      alt={`${cleanName} icon`}
      width={size}
      height={size}
      unoptimized
      onError={() => setHasError(true)}
      className={`${className} object-contain transition-transform duration-200 group-hover:scale-110 flex-shrink-0`}
    />
  );
}

export const BrandIcon = GoogleSkillIcon;
